import{_ as t,o as i,c as o,a5 as r}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/admin-management/3-10-12-export-report-file-pdf/report3_spec.md","filePath":"feature/admin-management/3-10-12-export-report-file-pdf/report3_spec.md"}'),l={name:"feature/admin-management/3-10-12-export-report-file-pdf/report3_spec.md"};function g(h,n,u,e,s,c){return i(),o("div",null,[...n[0]||(n[0]=[r("<p><strong>3.10.12 Export Report File PDF (Xuất Báo Cáo Tài Chính và Kiểm Toán Người Dùng PDF)</strong></p><p><strong>Function Trigger</strong></p><p>Bắt đầu khi Quản trị viên (ADMIN) nhấn nút &quot;Xuất Báo Cáo PDF&quot; tại các màn hình quản trị hệ thống.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: ADMIN. Quản trị viên có thẩm quyền xuất tài liệu báo cáo phục vụ lưu trữ và kiểm toán.</li><li><strong>Purpose</strong>: Xuất A4 về tài chính, trạng thái user/strike, phiên bản kiểm duyệt và tổng quan nền tảng theo cùng định nghĩa/múi giờ màn hình nguồn. Phạm vi Monitoring vẫn thuộc FR 3.10.3.</li><li><strong>Interface</strong>: Modal Xuất Báo Cáo PDF (SCR-ADM-11), gồm bộ chọn loại báo cáo, chọn khoảng ngày, tùy chọn trường dữ liệu và nút tải file.</li><li><strong>Data Processing</strong>: Hệ thống kiểm tra quyền ADMIN (BR-35, BR-65), tiếp nhận phân loại báo cáo và khoảng ngày, truy vấn dữ liệu nguồn, định dạng tài liệu PDF chuẩn A4 có tiêu đề, số trang và dấu thời gian, lưu file tạm và trả về đường dẫn tải xuống an toàn (BR-16).</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Modal Xuất Báo Cáo PDF (SCR-ADM-11):</p><ul><li>Left/Header: Tiêu đề hộp thoại &quot;Xuất Báo Cáo Hệ Thống PDF&quot; kèm biểu tượng tài liệu.</li><li>Center: Loại revenue/user/moderation/platform, khoảng ngày, múi giờ UTC / Asia/Ho_Chi_Minh, phần/biểu đồ và xem trước tóm tắt. Báo cáo user tách thẻ hiệu lực, quy đổi, gỡ, hết hạn; tài chính tách MRR/ARR và thu/hoàn tiền.</li><li>Buttons: Nút &quot;Tải xuống file PDF&quot; (màu xanh), Nút &quot;Hủy bỏ&quot;.</li><li>Footer: Ghi chú tài liệu mật nội bộ BrandHub và thời gian hết hạn của liên kết tải xuống (24 giờ).</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: reportType (enum: &quot;revenue&quot;, &quot;user&quot;, &quot;moderation&quot;, &quot;platform&quot;), startDate (YYYY-MM-DD), endDate (YYYY-MM-DD).</li><li><strong>Input optional</strong>: includeCharts, sections, timezone (UTC/Asia/Ho_Chi_Minh, mặc định Asia/Ho_Chi_Minh), bộ lọc màn hình nguồn.</li><li><strong>System data</strong>: adminId (UUID Admin yêu cầu), generatedReportId (UUID), downloadUrl (liên kết tải tạm thời), expiresAt (thời hạn 24 giờ).</li><li><strong>Output</strong>: Đối tượng JSON chứa { reportId, downloadUrl, fileName, fileSize, expiresAt } kèm mã HTTP 200 OK.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-65</strong>: Chỉ ADMIN yêu cầu/xuất báo cáo toàn nền tảng.</li><li><strong>BR-35</strong>: Kiểm tra quyền trước truy vấn và trước truy cập tải có kiểm soát.</li><li><strong>BR-16</strong>: Audit loại báo cáo, người yêu cầu, bộ lọc, kỳ, múi giờ, asOf, file và hạn tải.</li><li><strong>BR-80</strong>: Khớp định nghĩa màn hình FR 3.10.2/5/6/9/11: trạng thái strike, liên kết quy đổi, hạn khóa tài khoản, MRR/ARR, tiền thu gộp/hoàn/ròng; không dùng Trust Score thay thế.</li><li><strong>BR-65</strong>: Lưu thời điểm bằng UTC; báo cáo cho chọn UTC hoặc Asia/Ho_Chi_Minh (mặc định). Tính biên ngày và nhóm ngày/tháng theo múi giờ đã chọn; trả múi giờ trong response, bản xuất và khóa cache.</li><li><strong>BR-65</strong>: Giữ khổ A4, font tiếng Việt, header, số trang và link tải bảo mật 24 giờ. Không tạo dữ liệu lịch sử Monitoring giả hoặc mở rộng FR 3.10.3.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Người dùng không có quyền ADMIN → Display: MSG39</li><li>Không có dữ liệu trong khoảng ngày đã chọn → Display: MSG122</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>Admin nhấn nút &quot;Xuất Báo Cáo PDF&quot; trên thanh công cụ quản trị.</li><li>Hệ thống hiển thị modal tùy chọn SCR-ADM-11.</li><li>Admin chọn Loại báo cáo, chọn Khoảng thời gian và tích chọn các mục cần xuất.</li><li>Admin nhấn nút &quot;Tải xuống file PDF&quot;.</li><li>Hệ thống xác thực quyền hạn (BR-35, BR-65) và truy vấn dữ liệu tương ứng trong khoảng ngày đã chọn.</li><li>Hệ thống tạo file PDF định dạng A4 chuẩn theo mẫu.</li><li>Hệ thống tạo liên kết tải xuống tạm thời và kích hoạt trình duyệt tự động tải file PDF về máy tính của Admin.</li><li>Hệ thống đóng modal và lưu nhật ký kiểm toán (BR-16).</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>1.a1: Nếu người dùng không có vai trò ADMIN, hệ thống từ chối và hiển thị MSG39.</li><li>5.a1: Nếu không có bản ghi nào trong khoảng ngày đã chọn, hệ thống thông báo MSG122 và không tạo file rỗng.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>File PDF báo cáo được tạo thành công và lưu tạm trên máy chủ trong 24 giờ.</li><li>Trình duyệt của Admin tải file PDF về máy tính.</li><li>Một bản ghi được lưu vào bảng audit_logs ghi nhận thông tin báo cáo đã xuất (BR-16).</li></ul>",14)])])}const m=t(l,[["render",g]]);export{p as __pageData,m as default};
